def canSplitDescending(digits):
    n = len(digits)

    def go(i, prev):
        if i == n:
            return True
        want = prev - 1
        if want < 0:
            return False
        for j in range(i + 1, n + 1):
            v = int(digits[i:j])
            if v > want:
                break
            if v == want and go(j, v):
                return True
        return False

    for j in range(1, n):
        if go(j, int(digits[:j])):
            return True
    return False
